graphql.query:
query($representations: [_Any!]!) {
  _entities(representations: $representations) {
    ... on Product {
      __typename
      id
      price {
        amount
        currency
      }
      availableQuantity
      averageRating
    }
  }
}

query($representations: [_Any!]!) {
  _entities(representations: $representations) {
    ... on Product {
      id
      reviews(first: 2) {
        totalCount
        nodes {
          rating
          author {
            id
          }
        }
        pageInfo {
          hasNextPage
        }
      }
    }
  }
}

query($customerId: ID!) {
  ordersByCustomer(customerId: $customerId) {
    id
    placedAt
    total {
      amount
      currency
    }
    lines {
      quantity
      unitPrice {
        amount
        currency
      }
      product {
        id
      }
    }
  }
}

query Unreviewed($sku: String!) {
  productBySku(sku: $sku) {
    id
    sku
    title
  }
}

query($representations: [_Any!]!) {
  _entities(representations: $representations) {
    ... on Product {
      id
      averageRating
      reviews(first: 5) {
        totalCount
        pageInfo {
          hasNextPage
        }
        nodes {
          id
          rating
        }
      }
    }
  }
}

mutation SubmitReview($input: SubmitReviewInput!) {
  submitReview(input: $input) {
    review {
      id
      rating
    }
    errors {
      __typename
      ... on Error {
        message
        code
      }
      ... on RatingOutOfRangeError {
        min
        max
      }
    }
  }
}

